{"path": "src/components/home.tsx", "content": ""use client";

import { useState } from "react";
import { AnimatePresence, MotionConfig, motion } from "motion/react";
import { Droplets, FlaskConical, Factory, Truck, ArrowDown } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { FadeIn, HoverLift, Stagger, StaggerItem } from "@/components/motion";
import { ThemeToggle } from "@/components/theme-toggle";
import { bottlingSteps, makingSteps, mineralInfo, waterTypes, type Step } from "@/lib/water-data";

const nav = [
  { href: "#minerals", label: "Minerals" },
  { href: "#making", label: "Making" },
  { href: "#journey", label: "Distribution" },
];

function SectionHead({ icon: Icon, kicker, title, text }: { icon: typeof Droplets; kicker: string; title: string; text: string }) {
  return (
    <FadeIn className="mb-10 max-w-2xl">
      <Badge variant="secondary" className="mb-3 gap-1.5 rounded-full px-3 py-1">
        <Icon className="size-3.5" /> {kicker}
      </Badge>
      <h2 className="text-3xl font-bold sm:text-4xl">{title}</h2>
      <p className="mt-3 text-muted-foreground">{text}</p>
    </FadeIn>
  );
}

function Minerals() {
  const [id, setId] = useState(waterTypes[0].id);
  const water = waterTypes.find((w) => w.id === id) ?? waterTypes[0];
  const max = Math.max(...water.minerals.map((m) => m.mg));
  return (
    <section id="minerals" className="mx-auto max-w-6xl scroll-mt-20 px-4 py-20">
      <SectionHead icon={FlaskConical} kicker="Minerals" title="What's actually in the bottle?" text="Every water carries dissolved minerals from the rock it has travelled through. Compare typical profiles (illustrative values, mg per litre)." />
      <Tabs value={id} onValueChange={setId}>
        <TabsList className="mb-6 h-auto flex-wrap">
          {waterTypes.map((w) => (
            <TabsTrigger key={w.id} value={w.id}>{w.name}</TabsTrigger>
          ))}
        </TabsList>
      </Tabs>
      <div className="grid gap-6 lg:grid-cols-5">
        <Card className="p-6 lg:col-span-3">
          <AnimatePresence mode="wait">
            <motion.div key={water.id} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.25 }}>
              <h3 className="text-xl font-semibold">{water.name}</h3>
              <p className="mb-5 text-sm text-muted-foreground">{water.tagline}</p>
              <div className="mb-6 grid grid-cols-2 gap-3">
                <div className="rounded-xl bg-secondary p-4"><div className="text-2xl font-bold text-primary">{water.tds}</div><div className="text-xs text-muted-foreground">TDS (mg/L total dissolved solids)</div></div>
                <div className="rounded-xl bg-secondary p-4"><div className="text-2xl font-bold text-primary">{water.ph}</div><div className="text-xs text-muted-foreground">pH level</div></div>
              </div>
              <ul className="space-y-3">
                {water.minerals.map((m) => (
                  <li key={m.symbol} className="flex items-center gap-3 text-sm">
                    <span className="w-12 font-mono font-semibold">{m.symbol}</span>
                    <div className="h-2.5 flex-1 overflow-hidden rounded-full bg-muted">
                      <motion.div className="h-full rounded-full bg-primary" initial={{ width: 0 }} animate={{ width: `${Math.max((m.mg / max) * 100, 3)}%` }} transition={{ duration: 0.6, ease: "easeOut" }} />
                    </div>
                    <span className="w-16 text-right tabular-nums text-muted-foreground">{m.mg} mg</span>
                  </li>
                ))}
              </ul>
            </motion.div>
          </AnimatePresence>
        </Card>
        <Stagger className="grid gap-3 sm:grid-cols-2 lg:col-span-2 lg:grid-cols-1">
          {mineralInfo.map((m) => (
            <StaggerItem key={m.symbol}>
              <Card className="flex-row items-start gap-3 p-4">
                <span className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-primary font-mono text-xs font-bold text-primary-foreground">{m.symbol}</span>
                <div><div className="font-semibold">{m.name}</div><p className="text-sm text-muted-foreground">{m.role}</p></div>
              </Card>
            </StaggerItem>
          ))}
        </Stagger>
      </div>
    </section>
  );
}

function Steps({ steps }: { steps: Step[] }) {
  const [open, setOpen] = useState(0);
  return (
    <ol className="space-y-3">
      {steps.map((s, i) => (
        <FadeIn key={s.title} delay={i * 0.04}>
          <HoverLift>
            <button onClick={() => setOpen(open === i ? -1 : i)} aria-expanded={open === i} className="w-full rounded-2xl border bg-card p-5 text-left shadow-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring">
              <div className="flex items-center gap-4">
                <span className="flex size-10 shrink-0 items-center justify-center rounded-full bg-primary font-bold text-primary-foreground">{i + 1}</span>
                <div>
                  <div className="font-semibold">{s.title}</div>
                  <p className="text-sm text-muted-foreground">{s.body}</p>
                </div>
              </div>
              <AnimatePresence initial={false}>
                {open === i && (
                  <motion.p initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.25 }} className="overflow-hidden pl-14 pt-3 text-sm text-primary">
                    {s.detail}
                  </motion.p>
                )}
              </AnimatePresence>
            </button>
          </HoverLift>
        </FadeIn>
      ))}
    </ol>
  );
}

export function Home() {
